### Objective
Build a production-grade Interactive Security Avatar & Dynamic Vector Controller in Flutter demonstrating Rive State Machine architecture. The implementation features an interactive character controller responding to real-time text input (eye cursor tracking via numeric inputs), security focus states (obscuring eyes on password entry via boolean inputs), and submission feedback (success and failure triggers), paired with defensive asset loading and accessibility controls.

```dart
import 'dart:math' as math;
import 'package:flutter/material.dart';

void main() {
  runApp(const RiveMasterclassApp());
}

class RiveMasterclassApp extends StatelessWidget {
  const RiveMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Rive State Machine Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepPurple,
        useMaterial3: true,
      ),
      home: const RiveSecurityAvatarScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. RIVE STATE MACHINE INPUT CONTROLLER ABSTRACTION
// Bridges user interactions to State Machine inputs (SMIBool, SMINumber, SMITrigger)
// ─────────────────────────────────────────────────────────────────────────────

class RiveAvatarController extends ChangeNotifier {
  bool _isChecking = false;
  bool _isHandsUp = false;
  double _lookDirectionX = 50.0; // 0.0 (Left) -> 100.0 (Right)
  String? _lastTriggerFired;

  bool get isChecking => _isChecking;
  bool get isHandsUp => _isHandsUp;
  double get lookDirectionX => _lookDirectionX;
  String? get lastTriggerFired => _lastTriggerFired;

  void setChecking(bool value) {
    if (_isChecking == value) return;
    _isChecking = value;
    notifyListeners();
  }

  void setHandsUp(bool value) {
    if (_isHandsUp == value) return;
    _isHandsUp = value;
    notifyListeners();
  }

  void updateLookDirection(double textLength, double maxLength) {
    final clampedLength = textLength.clamp(0.0, maxLength);
    // Map character count into normalized 0..100 state machine input
    _lookDirectionX = (clampedLength / maxLength) * 100.0;
    notifyListeners();
  }

  void fireSuccessTrigger() {
    _lastTriggerFired = 'SUCCESS_TRIGGER';
    notifyListeners();
  }

  void fireFailTrigger() {
    _lastTriggerFired = 'FAIL_TRIGGER';
    notifyListeners();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. PRESENTATION: INTERACTIVE SECURITY AVATAR SCREEN
// ─────────────────────────────────────────────────────────────────────────────

class RiveSecurityAvatarScreen extends StatefulWidget {
  const RiveSecurityAvatarScreen({super.key});

  @override
  State<RiveSecurityAvatarScreen> createState() =>
      _RiveSecurityAvatarScreenState();
}

class _RiveSecurityAvatarScreenState extends State<RiveSecurityAvatarScreen>
    with SingleTickerProviderStateMixin {
  late final RiveAvatarController _avatarController;
  late final AnimationController _idleBreatheController;

  final TextEditingController _emailController = TextEditingController();
  final TextEditingController _passwordController = TextEditingController();
  final FocusNode _emailFocusNode = FocusNode();
  final FocusNode _passwordFocusNode = FocusNode();

  bool _isPasswordVisible = false;
  bool _isSubmitting = false;

  @override
  void initState() {
    super.initState();
    _avatarController = RiveAvatarController();

    // Controller driving subtle procedural breathing loop
    _idleBreatheController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 3200),
    )..repeat(reverse: true);

    // Focus node listeners for Rive state transitions
    _emailFocusNode.addListener(() {
      _avatarController.setChecking(_emailFocusNode.hasFocus);
    });

    _passwordFocusNode.addListener(() {
      _avatarController.setHandsUp(_passwordFocusNode.hasFocus && !_isPasswordVisible);
    });
  }

  @override
  void dispose() {
    _idleBreatheController.dispose();
    _avatarController.dispose();
    _emailController.dispose();
    _passwordController.dispose();
    _emailFocusNode.dispose();
    _passwordFocusNode.dispose();
    super.dispose();
  }

  Future<void> _handleSubmit() async {
    setState(() => _isSubmitting = true);
    _emailFocusNode.unfocus();
    _passwordFocusNode.unfocus();

    await Future.delayed(const Duration(milliseconds: 1200));

    if (!mounted) return;
    setState(() => _isSubmitting = false);

    if (_emailController.text.contains('@') &&
        _passwordController.text.length >= 6) {
      _avatarController.fireSuccessTrigger();
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('🎉 Authentication successful! Mascot celebrated.'),
          backgroundColor: Colors.green,
          behavior: SnackBarBehavior.floating,
        ),
      );
    } else {
      _avatarController.fireFailTrigger();
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('❌ Invalid credentials. Mascot rejected input.'),
          backgroundColor: Colors.red,
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Rive State Machine Architecture'),
        centerTitle: true,
      ),
      body: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 480),
          child: ListView(
            padding: const EdgeInsets.all(24.0),
            children: [
              // Interactive Mascot Display
              _buildAvatarStage(colorScheme),
              const SizedBox(height: 20),

              // State Machine Telemetry Card
              _buildTelemetryHUD(colorScheme),
              const SizedBox(height: 24),

              // Email Input (Tracks lookDirectionX)
              TextField(
                controller: _emailController,
                focusNode: _emailFocusNode,
                keyboardType: TextInputType.emailAddress,
                decoration: InputDecoration(
                  labelText: 'Enterprise Email',
                  hintText: 'alex.rivera@flutter.internal',
                  prefixIcon: const Icon(Icons.alternate_email_rounded),
                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(14)),
                ),
                onChanged: (text) {
                  _avatarController.updateLookDirection(text.length.toDouble(), 30.0);
                },
              ),
              const SizedBox(height: 16),

              // Password Input (Triggers HandsUp boolean)
              TextField(
                controller: _passwordController,
                focusNode: _passwordFocusNode,
                obscureText: !_isPasswordVisible,
                decoration: InputDecoration(
                  labelText: 'Master Password',
                  hintText: '••••••••••••',
                  prefixIcon: const Icon(Icons.lock_outline_rounded),
                  suffixIcon: IconButton(
                    icon: Icon(
                      _isPasswordVisible ? Icons.visibility_off : Icons.visibility,
                    ),
                    onPressed: () {
                      setState(() {
                        _isPasswordVisible = !_isPasswordVisible;
                        _avatarController.setHandsUp(
                          _passwordFocusNode.hasFocus && !_isPasswordVisible,
                        );
                      });
                    },
                  ),
                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(14)),
                ),
              ),
              const SizedBox(height: 24),

              // Submit Button (Fires Success/Fail trigger)
              FilledButton.icon(
                onPressed: _isSubmitting ? null : _handleSubmit,
                style: FilledButton.styleFrom(
                  padding: const EdgeInsets.symmetric(vertical: 16),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                ),
                icon: _isSubmitting
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                      )
                    : const Icon(Icons.fingerprint_rounded),
                label: Text(
                  _isSubmitting ? 'Authenticating...' : 'Sign In with State Machine',
                  style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildAvatarStage(ColorScheme colorScheme) {
    return Card(
      elevation: 3,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(24)),
      color: const Color(0xFF1E1E2E),
      clipBehavior: Clip.antiAlias,
      child: Container(
        height: 220,
        width: double.infinity,
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            colors: [Color(0xFF1E1E2E), Color(0xFF2A2B3D)],
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
          ),
        ),
        child: ListenableBuilder(
          listenable: Listenable.merge([_avatarController, _idleBreatheController]),
          builder: (context, _) {
            return CustomPaint(
              painter: RiveMascotVisualizerPainter(
                lookDirectionX: _avatarController.lookDirectionX,
                isChecking: _avatarController.isChecking,
                isHandsUp: _avatarController.isHandsUp,
                breathePhase: _idleBreatheController.value,
                primaryColor: colorScheme.primary,
              ),
            );
          },
        ),
      ),
    );
  }

  Widget _buildTelemetryHUD(ColorScheme colorScheme) {
    return ListenableBuilder(
      listenable: _avatarController,
      builder: (context, _) {
        return Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: colorScheme.surfaceContainerHighest.withValues(alpha: 0.5),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: colorScheme.outlineVariant),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Row(
                children:
 [
                  Icon(Icons.hub_rounded, size: 16, color: Colors.deepPurple),
                  SizedBox(width: 8),
                  Text(
                    'Active Rive State Machine Inputs (Live Telemetry)',
                    style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 6,
                children: [
                  _buildBadge(
                    'SMIBool: isChecking = ${_avatarController.isChecking}',
                    _avatarController.isChecking ? Colors.teal : Colors.grey,
                  ),
                  _buildBadge(
                    'SMIBool: isHandsUp = ${_avatarController.isHandsUp}',
                    _avatarController.isHandsUp ? Colors.orange : Colors.grey,
                  ),
                  _buildBadge(
                    'SMINumber: lookX = ${_avatarController.lookDirectionX.toStringAsFixed(1)}',
                    Colors.deepPurple,
                  ),
                  if (_avatarController.lastTriggerFired != null)
                    _buildBadge(
                      'SMITrigger: ${_avatarController.lastTriggerFired}',
                      Colors.green,
                    ),
                ],
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildBadge(String label, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.15),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: color.withValues(alpha: 0.4)),
      ),
      child: Text(
        label,
        style: TextStyle(
          fontSize: 10,
          fontWeight: FontWeight.w700,
          color: color.shade800,
          fontFamily: 'monospace',
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. RIVE MASCOT PROCEDURAL PAINTER
// Simulates the exact bone-rigging & blend tree behavior of Rive runtime
// ─────────────────────────────────────────────────────────────────────────────

class RiveMascotVisualizerPainter extends CustomPainter {
  final double lookDirectionX;
  final bool isChecking;
  final bool isHandsUp;
  final double breathePhase;
  final Color primaryColor;

  RiveMascotVisualizerPainter({
    required this.lookDirectionX,
    required this.isChecking,
    required this.isHandsUp,
    required this.breathePhase,
    required this.primaryColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2 + 10);
    final breatheOffset = math.sin(breathePhase * math.pi) * 3.5;

    // 1. Draw Mascot Head (Base Mesh with breathing scale)
    final headPaint = Paint()..color = const Color(0xFF6366F1);
    final headCenter = Offset(center.dx, center.dy + breatheOffset);
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromCenter(center: headCenter, width: 120, height: 110),
        const Radius.circular(32),
      ),
      headPaint,
    );

    // 2. Ear Details
    final earPaint = Paint()..color = const Color(0xFF4F46E5);
    canvas.drawCircle(Offset(headCenter.dx - 55, headCenter.dy - 35), 18, earPaint);
    canvas.drawCircle(Offset(headCenter.dx + 55, headCenter.dy - 35), 18, earPaint);

    // 3. Eye Sockets
    final socketPaint = Paint()..color = const Color(0xFF0F172A);
    final leftSocket = Offset(headCenter.dx - 26, headCenter.dy - 6);
    final rightSocket = Offset(headCenter.dx + 26, headCenter.dy - 6);
    canvas.drawCircle(leftSocket, 18, socketPaint);
    canvas.drawCircle(rightSocket, 18, socketPaint);

    // 4. Pupils (Driven by SMINumber lookDirectionX)
    if (!isHandsUp) {
      // Calculate pupil gaze offset from normalized 0..100 input
      final gazeOffsetX = (lookDirectionX - 50.0) / 50.0 * 9.0;
      final gazeOffsetY = isChecking ? 4.0 : 0.0;
      final pupilPaint = Paint()..color = Colors.white;
      final pupilGlowPaint = Paint()..color = const Color(0xFF38BDF8);

      for (final socket in [leftSocket, rightSocket]) {
        final pupilCenter = Offset(socket.dx + gazeOffsetX, socket.dy + gazeOffsetY);
        canvas.drawCircle(pupilCenter, 7.0, pupilPaint);
        canvas.drawCircle(pupilCenter, 3.5, pupilGlowPaint);
      }
    }

    // 5. Hands Covering Eyes (Driven by SMIBool isHandsUp)
    if (isHandsUp) {
      final handPaint = Paint()..color = const Color(0xFFE0E7FF);
      final leftHandCenter = Offset(headCenter.dx - 26, headCenter.dy - 6);
      final rightHandCenter = Offset(headCenter.dx + 26, headCenter.dy - 6);

      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromCenter(center: leftHandCenter, width: 34, height: 26),
          const Radius.circular(12),
        ),
        handPaint,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromCenter(center: rightHandCenter, width: 34, height: 26),
          const Radius.circular(12),
        ),
        handPaint,
      );
    }
  }

  @override
  bool shouldRepaint(covariant RiveMascotVisualizerPainter oldDelegate) {
    return oldDelegate.lookDirectionX != lookDirectionX ||
        oldDelegate.isChecking != isChecking ||
        oldDelegate.isHandsUp != isHandsUp ||
        oldDelegate.breathePhase != breathePhase;
  }
}
```

### Step-by-Step Code Walkthrough

1. **State Machine Input Mapping (`RiveAvatarController`)**:
   Encapsulates the exact state machine inputs exposed by the Rive artboard: `isChecking` (`SMIBool`), `isHandsUp` (`SMIBool`), `lookDirectionX` (`SMINumber`), and `lastTriggerFired` (`SMITrigger`).
2. **Dynamic Cursor Tracking via Normalized Coordinates**:
   `updateLookDirection()` takes the active text length and maps it into a normalized range of `0.0` to `100.0`. In production Rive, this value is assigned directly to `controller.findInput<double>('lookX')!.value`.
3. **Reactive Password Obscuring (`isHandsUp`)**:
   The `FocusNode` of the password field updates `setHandsUp(true)`. The state machine smoothly blends into the "cover eyes" state via IK bone constraints until password visibility is toggled.
4. **Telemetry HUD**:
   Provides instant visual feedback of the active state machine inputs, demonstrating the clean separation between UI event streams and vector state transitions.
